import express, { NextFunction, Request, Response } from "express";
import { OrderService } from "../application/order-service";
import { DomainError } from "../domain/errors";
import { fulfilmentStates, FulfilmentState, Order, OrderState } from "../domain/order";
import { Product } from "../domain/product";
import { InMemoryOrderRepository, InMemoryProductRepository } from "./in-memory-repositories";

const orderView = (order: Order) => ({ id: order.id, state: order.state, items: order.items });
const productView = (product: Product) => ({
  id: product.id, name: product.name, stock: product.stockLevel,
  reserved: product.reservedStock, available: product.availableStock,
});

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

export function createApp(service = new OrderService(new InMemoryProductRepository(), new InMemoryOrderRepository())) {
  const app = express();
  app.use(express.json());

  app.post("/products", (req, res, next) => {
    try {
      if (!isRecord(req.body)) throw new DomainError("INVALID_PRODUCT", "Request body must be an object.");
      const product = service.addProduct({ id: req.body.id as string, name: req.body.name as string, stock: req.body.stock as number });
      res.status(201).json(productView(product));
    } catch (error) { next(error); }
  });
  app.get("/products", (_req, res) => res.json(service.listProducts().map(productView)));

  app.post("/orders", (req, res, next) => {
    try {
      if (!isRecord(req.body) || !Array.isArray(req.body.items)) throw new DomainError("INVALID_ORDER", "items must be an array.");
      const order = service.placeOrder({ items: req.body.items as { productId: string; quantity: number }[] });
      res.status(201).json(orderView(order));
    } catch (error) { next(error); }
  });
  app.get("/orders", (req, res, next) => {
    try {
      const state = req.query.state;
      if (state !== undefined && (typeof state !== "string" || ![...fulfilmentStates, "cancelled"].includes(state))) {
        throw new DomainError("INVALID_STATE", "Unknown order state.");
      }
      res.json(service.listOrders(state as OrderState | undefined).map(orderView));
    } catch (error) { next(error); }
  });
  app.patch("/orders/:id/state", (req, res, next) => {
    try {
      if (!isRecord(req.body) || !fulfilmentStates.includes(req.body.state as FulfilmentState)) {
        throw new DomainError("INVALID_STATE", "state must be a fulfilment state.");
      }
      res.json(orderView(service.progressOrder(req.params.id, req.body.state as FulfilmentState)));
    } catch (error) { next(error); }
  });
  app.post("/orders/:id/cancel", (req, res, next) => {
    try { res.json(orderView(service.cancelOrder(req.params.id))); } catch (error) { next(error); }
  });

  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (error instanceof DomainError) {
      const status = error.code === "ORDER_NOT_FOUND" || error.code === "PRODUCT_NOT_FOUND" ? 404
        : error.code === "INSUFFICIENT_STOCK" ? 409 : 400;
      res.status(status).json({ error: error.code, message: error.message });
      return;
    }
    res.status(500).json({ error: "INTERNAL_ERROR", message: "Unexpected server error." });
  });
  return app;
}

